create extension if not exists pgcrypto;
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,quantity integer not null default 0 check(quantity>=0),minimum_quantity integer not null default 1 check(minimum_quantity>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.shopping_items(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,name text not null,quantity integer not null default 1 check(quantity>0),completed boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.products enable row level security;alter table public.shopping_items enable row level security;
drop policy if exists products_select on public.products;drop policy if exists products_insert on public.products;drop policy if exists products_update on public.products;drop policy if exists products_delete on public.products;drop policy if exists shopping_select on public.shopping_items;drop policy if exists shopping_insert on public.shopping_items;drop policy if exists shopping_update on public.shopping_items;drop policy if exists shopping_delete on public.shopping_items;
create policy products_select on public.products for select to anon,authenticated using(true);create policy products_insert on public.products for insert to anon,authenticated with check(true);create policy products_update on public.products for update to anon,authenticated using(true) with check(true);create policy products_delete on public.products for delete to anon,authenticated using(true);
create policy shopping_select on public.shopping_items for select to anon,authenticated using(true);create policy shopping_insert on public.shopping_items for insert to anon,authenticated with check(true);create policy shopping_update on public.shopping_items for update to anon,authenticated using(true) with check(true);create policy shopping_delete on public.shopping_items for delete to anon,authenticated using(true);
